// pxInsName isn't updated until the first DB.save(), so get here if necessary
String pxObjClass = myStepPage.getClassName();
if (pxObjClass.length() > 0)
{
	String insName = "";
	ClassDefinition instanceClass = tools.getDatabase().getClassDef(pxObjClass);
	if (instanceClass != null)
		insName = tools.getDatabase().getInstanceName(myStepPage, instanceClass);
	if (insName.length() == 0)
	{
		myStepPage.getProperty(".pxInsName").addMessage("KeyValueRequired");
		nextBlock = "***";
	}
}

String systemUpdateInfo = tools.getParamValue("updateType");

//Split the updateType param to extract pyID and Action name
//Param should be passed as "SystemUpdate:"+pyID+":ActionName"
String[] systemUpdateInfoDetails =systemUpdateInfo.split(":");


//If the parm is not passed as expected , the list page is not set with info
if(systemUpdateInfoDetails.length==4){

 ClipboardPage primaryPage=tools.getPrimaryPage();

 primaryPage.putString(".pxSystemUpdateDetailsList(<PREPEND>).pyID",systemUpdateInfoDetails[1]);
 primaryPage.putString(".pxSystemUpdateDetailsList(1).pyActionName",systemUpdateInfoDetails[2]);
 primaryPage.putString(".pxSystemUpdateDetailsList(1).pyClassName",systemUpdateInfoDetails[3]);

 primaryPage.putString(".pxSystemUpdateDetailsList(1).pxUpdateDateTime",primaryPage.getString(".pxUpdateDateTime"));
 primaryPage.putString(".pxSystemUpdateDetailsList(1).pxUpdateOpName",primaryPage.getString(".pxUpdateOpName"));


}

// If the object already has errors, it will not save, but we must still invalidate
// this transaction in case the customer has commits in place.
if (myStepPage.hasMessages()){
    String messages = myStepPage.getMessagesAll();
    ClipboardPage originalPage = myStepPage;
    myStepPage = tools.createPage(originalPage.getClassName(),"");

	// We probably could get away with just putting pyID on the new page, but on the
	// off chance that they have specified additional key parts in the class, just
	// copy the whole thing.  From a performance standpoint, getting to this point
	// with messages on the page is very rare anyway.  Error handling should be done
	// before flow processing is started/resumed.
  	oLog.debug("From Recalcualte And Save Activity : " +messages);
    myStepPage.putAll(originalPage, ClipboardPage.PUTALL_KEEPNEW);
    myStepPage.addMessage(messages);
}

// If this is a new instance, we will 'save if new', otherwise regular save
boolean newObject = tools.getParamAsBoolean(PropertyInfo.TYPE_TRUEFALSE, "newObject");
try {
  tools.getDatabase().saveDeferred(myStepPage, newObject, true);
} catch (DatabaseException e) {
  // The engine tacks on "Trying to save an invalid page:" at the beginning
  // of the exception message and "Trying to save an invalid page: page is not valid"
  // to the end of the page message.  If the engine message does not
  // start with that, we must add it to the page (because that means the
  // engine did not add it for us)
  if (!e.getMessage().startsWith("Trying to save an invalid page:"))
  {
     myStepPage.addMessage(tools.getStepStatus().getLatestMessageName() + "\t" + tools.getStepStatus().getLatestMessageParms());
  }
}
